 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    frames = []
    # Each disconnected same-color shape is handled as its own object.
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            pts = []
            while stack:
                y, x = stack.pop()
                pts.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0, r1 = min(y for y,x in pts), max(y for y,x in pts)
            c0, c1 = min(x for y,x in pts), max(x for y,x in pts)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = [(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                         if y in (r0,r1) or x in (c0,c1)]
            if not all(g[y][x] == color for y,x in perimeter):
                continue
            interior = [(y,x) for y in range(r0+1,r1) for x in range(c0+1,c1)]
            frames.append((color,r0,r1,c0,c1,interior))
    # The frame containing a nonempty interior is the pattern donor.
    sources = [f for f in frames if any(g[y][x] != 0 for y,x in f[5])]
    if not sources:
        return g
    src = sources[0]
    sh, sw = src[2]-src[1]-1, src[4]-src[3]-1
    mask = [[g[src[1]+1+i][src[3]+1+j] != 0 for j in range(sw)] for i in range(sh)]
    for f in frames:
        if f is src:
            continue
        color,r0,r1,c0,c1,interior = f
        th, tw = r1-r0-1, c1-c0-1
        if (th,tw) == (sh,sw) and not any(g[y][x] != 0 for y,x in interior):
            for i in range(sh):
                for j in range(sw):
                    if mask[i][j]:
                        g[r0+1+i][c0+1+j] = color
    return g
